def avg_odds(n):
    sum = 0
    i = 1
    while i <= n:
        sum += i
        i += 2
    return sum / (i - 1)

def element_in_tuple(element, tuple_list):
    for t in tuple_list:
        if element in t:
            return True
    return False

def max_sum_bi_tonic_sub_seq(arr):
    n = len(arr)
    dp = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        dp[i][i] = arr[i]
    for i in range(n-1):
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                dp[i][j] = max(dp[i][j], dp[i][j-1] + arr[j])
            else:
                dp[i][j] = max(dp[i][j], dp[i+1][j] + arr[i])
    return max(dp[0][-1], dp[-1][-1])

def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def depth_of_dict(d):
    if not d:
        return 0
    else:
        return max(depth_of_dict(d.get(k, {})) + 1 for k in d)

def perrin(n):
    if n == 1:
        return 1
    elif n == 2:
        return 2
    else:
        return perrin(n-1) + perrin(n-2)

def contains_sublist(superlist, sublist):
    for i in range(len(superlist)):
        if superlist[i:i+len(sublist)] == sublist:
            return True
    return False

def common_divisor(a, b):
    if a == 0 or b == 0:
        return 0
    else:
        return common_divisor(b, a % b)

def max_profit(prices, k):
    if k == 0:
        return 0
    if k == 1:
        return max(prices) - min(prices)
    max_profit = 0
    for i in range(k):
        max_profit = max(max_profit, prices[i] - prices[i - 1])
    for i in range(k, len(prices)):
        max_profit = max(max_profit, prices[i] - prices[i - k])
    return max_profit

def find_bi_tonic_subsequence(arr):
    n = len(arr)
    dp = [[0 for _ in range(n)] for _ in range(n)]
    max_sum = 0

    for i in range(1, n):
        for j in range(i):
            dp[i][j] = max(arr[i] + dp[i - 1][j], arr[j] + dp[i][j - 1])

    max_sum = max(dp[n - 1][n - 2] + dp[n - 2][n - 1], dp[n - 1][n - 1])

    return max_sum

