        return common_divisor(b, a % b)

def subset_sum(set, sum):
    if sum == 0:
        return True
    if sum < 0:
        return False
    for i in set:
        if subset_sum(set, sum - i):
            return True
    return False

def filter_dict(dct, func):
    """
    Returns a new dictionary with the same keys as dct, but only containing the values that
    pass the test implemented by the function func.
    """
    return {key: value for key, value in dct.items() if func(value)}

def exponentiation(base, exponent):
    result = (1, 1)
    for i in range(len(exponent)):
        result = (result[0]*base[i], result[1]*base[i])
        if exponent[i] > 0:
            result = (result[0]*result[0], result[1]*result[1])
    return result

