def average_of_odd_numbers(n):
    sum_of_odds = 0
    count_of_odds = 0
    i = 1
    while i <= n:
        if i % 2!= 0:
            sum_of_odds += i
            count_of_odds += 1
        i += 2
    return sum_of_odds / count_of_odds

