def power(a, b):
    if b == 0:
        return 1
    elif b == 1:
        return a
    elif b % 2 == 0:
        return power(a * a, b // 2)
    else:
        return a * power(a * a, b // 2)

def gcd(a, b):
    if b == 0:
        return a
    else:
        return gcd(b, a % b)

def gcd_of_array(arr):
    if len(arr) == 1:
        return arr[0]
    else:
        return gcd(arr[0], gcd_of_array(arr[1:]))

