def hexagon_grid(size):
    grid = []
    for i in range(size):
        row = []
        for j in range(6):
            x = i * 2 + j % 2 * 2 - 1
            y = i * 3 - j // 2 * 3
            row.append((x, y))
        grid.append(row)
    return grid

def pancake_sort(arr):
    n = len(arr)
    for i in range(n-1):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
        for j in range(n-i-1, n):
            if arr[j] < arr[j-1]:
                arr[j], arr[j-1] = arr[j-1], arr[j]
    return arr

def get_depth(d):
