def first_missing_positive(nums):
    """
    :type nums: List[int]
    :rtype: int
    """
    nums.sort()
    for i in range(len(nums)):
        if nums[i]!= i + 1:
            return i + 1
    return len(nums) + 1

def median(a, b, c):
    if a > b and a > c:
        return a
    elif b > a and b > c:
        return b
    elif c > a and c > b:
        return c
    else:
        return (a + b + c) / 3

